         settingsRepository.setToken(token);
       }
     });

     test('readThemeMode returns current theme mode from datasource', () {
       when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.dark);

       final result = settingsRepository.readThemeMode();

       expect(result, AppThemeMode.dark);
       verify(mockPreferenceDatasource.themeMode).called(1);
     });

     test('readThemeMode returns actual value for system theme mode', () {
       when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.system);

       final result = settingsRepository.readThemeMode();

       expect(result, AppThemeMode.system);
     });

     test('readThemeMode reflects setThemeMode value after initialization', () async {
       when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value('token'));
       when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.light);

       await settingsRepository.initAsyncData();

       settingsRepository.setThemeMode(AppThemeMode.dark);

       final result = settingsRepository.readThemeMode();

       expect(result, AppThemeMode.dark);
     });

     test('readThemeMode can be called after initAsyncData without throwing', () async {
       when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value('token'));
       when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.light);

       await settingsRepository.initAsyncData();

       expect(() => settingsRepository.readThemeMode(), returnsNormally);
     });
   });
 }
