      verify(mockPreferenceDatasource.themeMode).called(1);
    });

    test('readThemeMode returns actual value for system theme mode', () {
      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.system);

      final result = settingsRepository.readThemeMode();

      expect(result, AppThemeMode.system);
    });

