      when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value('token'));
      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.light);

      await settingsRepository.initAsyncData();

      expect(() => settingsRepository.readThemeMode(), returnsNormally);
    });
  });
}

